/**
 * Build the 20-minute presentation.
 *
 *   node scripts/build_deck.js        →  docs/presentation.pptx
 *
 * Figures come from docs/figures/*.png (generated by scripts/make_figures.py,
 * which reads the raw run records). The deck palette is taken from the figure
 * palette so charts sit on the slides without a colour clash: the slide surface
 * is the same FCFCFB the figures are drawn on.
 *
 * Structure follows docs/presentation-plan.md — 17 content slides timed to
 * 20:00, then 9 backup slides that are never presented, only jumped to.
 */

const pptxgen = require("pptxgenjs");
const path = require("path");

const ROOT = path.join(__dirname, "..");
const FIG = (n) => path.join(ROOT, "docs", "figures", n + ".png");

// ── palette ──────────────────────────────────────────────────────────────────
const DARK = "12203A";      // deep navy-slate: title, pivot, conclusion
const DARK2 = "1D3055";     // raised card on dark
const SURF = "FCFCFB";      // light surface — identical to the figure surface
const CARD = "F1F1ED";      // tinted card on light
const INK = "0B0B0B";
const INK2 = "52514E";
const INK3 = "7A7974";
const ACC = "2A78D6";       // figure slot 1
const WARN = "EB6834";      // figure slot 2
const PAPER = "FFFFFF";

const HEAD = "Cambria";     // safe-list serif, renders true-to-width in QA
const BODY = "Calibri";     // safe-list sans

const pres = new pptxgen();
pres.layout = "LAYOUT_WIDE";            // 13.33 x 7.5 in — set before any slide
pres.author = "Muhammad Sawaiz Naveed";
pres.title = "LLM-Driven Verilog Testbench Generation";

const W = 13.33, H = 7.5, M = 0.7;

// ── helpers ──────────────────────────────────────────────────────────────────

function slide(dark) {
  const s = pres.addSlide();
  s.background = { color: dark ? DARK : SURF };
  return s;
}

/** Slide title + optional deck. Returns the y where content may begin. */
function title(s, text, sub, dark) {
  s.addText(text, {
    x: M, y: 0.44, w: W - 2 * M, h: 0.62, isTextBox: true, margin: 0,
    fontFace: HEAD, fontSize: 30, bold: true, color: dark ? PAPER : INK,
  });
  if (sub) {
    s.addText(sub, {
      x: M, y: 1.10, w: W - 2 * M, h: 0.4, isTextBox: true, margin: 0,
      fontFace: BODY, fontSize: 15, color: dark ? "A8B6CE" : INK3,
    });
    return 1.75;
  }
  return 1.35;
}

/** Rounded tinted card — the deck's repeated motif. */
function card(s, x, y, w, h, dark) {
  s.addShape(pres.ShapeType.roundRect, {
    x, y, w, h, rectRadius: 0.08,
    fill: { color: dark ? DARK2 : CARD }, line: { color: dark ? DARK2 : CARD },
    shadow: { type: "outer", angle: 90, offset: 0.03, blur: 6,
              color: "000000", opacity: 0.07 },
  });
}

/** Oversized numeral + label — the stat motif. */
function stat(s, x, y, w, value, label, colour, dark, size) {
  s.addText(String(value), {
    x, y, w, h: 0.92, isTextBox: true, margin: 0,
    fontFace: HEAD, fontSize: size || 46, bold: true, color: colour,
  });
  s.addText(label, {
    x, y: y + 0.88, w, h: 0.62, isTextBox: true, margin: 0,
    fontFace: BODY, fontSize: 13, color: dark ? "A8B6CE" : INK2,
  });
}

function body(s, x, y, w, runs, dark, size) {
  s.addText(runs, {
    x, y, w, h: 0.4 * runs.length + 0.3, isTextBox: true, margin: 0,
    fontFace: BODY, fontSize: size || 16, color: dark ? "D7DFEC" : INK2,
    lineSpacingMultiple: 1.22,
  });
}

function bullets(s, x, y, w, items, dark, size) {
  s.addText(items.map((t, i) => ({
    text: t, options: { bullet: true, breakLine: i !== items.length - 1 },
  })), {
    x, y, w, h: 0.44 * items.length + 0.25, isTextBox: true, margin: 0,
    fontFace: BODY, fontSize: size || 16, color: dark ? "D7DFEC" : INK2,
    paraSpaceAfter: 7,
  });
}

function table(s, x, y, w, rows, colW, dark) {
  s.addTable(rows, {
    x, y, w, colW,
    fontFace: BODY, fontSize: 14, color: dark ? "D7DFEC" : INK,
    border: { type: "solid", pt: 1, color: dark ? "2B4470" : "E2E1DC" },
    fill: { color: dark ? DARK : PAPER },
    rowH: 0.34, valign: "middle", margin: 6,
  });
}

/** Figure, sized to fit a box while keeping aspect ratio. */
function figure(s, name, ratio, x, y, maxW, maxH) {
  let w = maxW, h = w / ratio;
  if (h > maxH) { h = maxH; w = h * ratio; }
  s.addImage({ path: FIG(name), x: x + (maxW - w) / 2, y: y + (maxH - h) / 2, w, h });
}

function kicker(s, text, dark) {
  s.addText(text, {
    x: M, y: 0.2, w: W - 2 * M, h: 0.3, isTextBox: true, margin: 0,
    fontFace: BODY, fontSize: 11, bold: true, charSpacing: 1.6,
    color: dark ? "6E88B4" : INK3,
  });
}

/** The line to actually say — bottom band on evidence slides. */
function takeaway(s, text, colour) {
  card(s, M, H - 1.18, W - 2 * M, 0.78, false);
  s.addText(text, {
    x: M + 0.24, y: H - 1.1, w: W - 2 * M - 0.48, h: 0.62, isTextBox: true, margin: 0,
    fontFace: BODY, fontSize: 15, bold: true, color: colour || INK,
    valign: "middle",
  });
}

/** Thirteen dots showing where in the pipeline this slide sits. */
function progress(s, idx, total) {
  const dw = 0.17, gap = 0.075;
  const x0 = W - M - (total * dw + (total - 1) * gap);
  for (let i = 0; i < total; i++) {
    s.addShape(pres.ShapeType.roundRect, {
      x: x0 + i * (dw + gap), y: 0.26, w: dw, h: 0.17, rectRadius: 0.05,
      fill: { color: i === idx ? ACC : "DEDDD8" },
      line: { color: i === idx ? ACC : "DEDDD8" },
    });
  }
}

// ═══════════════════════════════ SETUP ═══════════════════════════════════════════

